// 3D GLB Models & Asset Loader
const GLB={"eye":"","leg":"","torso":"","head":"","trunk":"","leaves":"","cap":"","hammer":"","tramp":"","arm":"","hurdle":"","rocket":""},AS={};
function loadAssets(){return new Promise(res=>{if(!THREE.GLTFLoader){res();return}const L=new THREE.GLTFLoader(),ks=Object.keys(GLB);let n=0;const done=()=>{if(++n>=ks.length)res()};
 ks.forEach(k=>{try{const b=Uint8Array.from(atob(GLB[k]),c=>c.charCodeAt(0)).buffer;L.parse(b,'',g=>{g.scene.updateMatrixWorld(true);let ge=null;g.scene.traverse(o=>{if(o.isMesh&&!ge){ge=o.geometry.clone();ge.applyMatrix4(o.matrixWorld)}});if(ge)AS[k]=ge;done()},()=>done())}catch(e){done()}});setTimeout(res,6000)})}
